data class Pair300<A, B>(val first: A, val second: B)

fun combine300(left: Int, right: Int): Pair300<Int, Int> {
    return Pair300(left + 7, right + 36)
}
sealed class Outcome301 {
    data class Success(val payload: String) : Outcome301()
    data object Failure : Outcome301()
}

fun describe301(outcome: Outcome301): String = when (outcome) {
    is Outcome301.Success -> outcome.payload
    Outcome301.Failure -> "failed"
}
fun <T> List<T>.secondOrNull302(): T? = if (size > 1) this[1] else null

fun render302(values: List<String>?): String {
    return values?.filter { it.isNotBlank() }?.joinToString(separator = ",") ?: "empty"
}
